"""Phase 11 — Self Governance.

The Governor continuously audits all engines, the knowledge system,
constitution compliance, engineering standards, and technical debt, then
generates improvement proposals. It never modifies engines automatically.
"""

from __future__ import annotations

import json
from dataclasses import dataclass, field

from .core import ENGINE_REGISTRY, Finding, Severity, utcnow
from .engine_contract import validate_all_engines


@dataclass
class ImprovementProposal:
    """A proposal generated by self-governance (never auto-applied)."""

    proposal_id: str
    target: str
    title: str
    severity: Severity
    reason: str
    actions: list[str] = field(default_factory=list)
    status: str = "proposed"


def audit_engines(registry: dict | None = None) -> list[Finding]:
    """Audit every governed engine for contract and responsibility gaps."""
    registry = registry or ENGINE_REGISTRY
    findings: list[Finding] = []
    contract_violations = validate_all_engines(registry)
    for violation in contract_violations:
        findings.append(Finding(
            id=f"SG-ENG-{len(findings) + 1:04d}",
            title="Engine contract violation",
            severity=Severity.MEDIUM,
            category="engine-communication",
            detail=violation,
        ))
    return findings


def audit_knowledge_system(knowledge_counts: dict | None = None) -> list[Finding]:
    """Audit knowledge system health (coverage and lifecycle hygiene)."""
    knowledge_counts = knowledge_counts or {}
    findings: list[Finding] = []
    empty = [kind for kind, count in knowledge_counts.items() if count == 0]
    if empty:
        findings.append(Finding(
            id="SG-KNW-0001",
            title="Knowledge categories empty",
            severity=Severity.LOW,
            category="knowledge",
            detail=f"Empty knowledge categories: {', '.join(sorted(empty))}",
        ))
    return findings


def generate_proposals(findings: list[Finding]) -> list[ImprovementProposal]:
    """Generate improvement proposals from audit findings.

    Proposals are advisory — they are recorded for a human/governor decision,
    never applied to engines automatically.
    """
    proposals: list[ImprovementProposal] = []
    for i, finding in enumerate(findings, start=1):
        proposals.append(ImprovementProposal(
            proposal_id=f"PROP-{i:04d}",
            target=finding.category,
            title=finding.title,
            severity=finding.severity,
            reason=finding.detail,
            actions=[f"Resolve '{finding.id}': {finding.title}"],
        ))
    return proposals


def save_proposals(proposals: list[ImprovementProposal], path) -> None:
    """Persist improvement proposals as a machine-readable JSON report."""
    path.parent.mkdir(parents=True, exist_ok=True)
    payload = {
        "generated_at": utcnow(),
        "proposals": [vars(p) for p in proposals],
    }
    path.write_text(json.dumps(payload, indent=2, ensure_ascii=False) + "\n",
                    encoding="utf-8")
